sys_variable_value.value:
(function execute(inputs, outputs) {
    var scriptInc = new global.AAPGlobalAPI();
    gs.info("Delete model Input sys_id: " + inputs.variable);
    var result = scriptInc.deleteRecord(inputs.variable);
    gs.info("Result: " + result);
    outputs.result = result;
})(inputs, outputs);

